// ─── Lead Reminder Helpers ───────────────────────────────
function getRelativeDueTime(dueAt) {
    const now = new Date();
    const due = new Date(dueAt);
    const diffMs = due.getTime() - now.getTime();
    const isOverdue = diffMs < 0;
    const absDiffMs = Math.abs(diffMs);
    const absDiffMins = Math.floor(absDiffMs / 60000);
    const absDiffHours = Math.floor(absDiffMins / 60);
    const absDiffDays = Math.floor(absDiffHours / 24);
    if (isOverdue) {
        if (absDiffDays > 0) return {
            text: `Overdue by ${absDiffDays}d`,
            isOverdue: true,
            isUrgent: true
        };
        if (absDiffHours > 0) return {
            text: `Overdue by ${absDiffHours}h`,
            isOverdue: true,
            isUrgent: true
        };
        return {
            text: 'Overdue',
            isOverdue: true,
            isUrgent: true
        };
    }
    // Not overdue yet
    if (absDiffMins <= 60) return {
        text: `Due in ${absDiffMins}m`,
        isOverdue: false,
        isUrgent: absDiffMins <= 60
    };
    if (absDiffHours <= 24) return {
        text: `Due in ${absDiffHours}h`,
        isOverdue: false,
        isUrgent: absDiffHours <= 1
    };
    return {
        text: `Due in ${absDiffDays}d`,
        isOverdue: false,
        isUrgent: false
    };
}
function getReminderColor(reminder) {
    const { isOverdue, isUrgent } = getRelativeDueTime(reminder.dueAt);
    if (isOverdue) return {
        bg: 'bg-red-500/5',
        border: 'border-l-red-500',
        text: 'text-red-500',
        dot: 'bg-red-500'
    };
    if (isUrgent) return {
        bg: 'bg-amber-500/5',
        border: 'border-l-amber-500',
        text: 'text-amber-500',
        dot: 'bg-amber-500'
    };
    return {
        bg: 'bg-emerald-500/5',
        border: 'border-l-emerald-500',
        text: 'text-emerald-500',
        dot: 'bg-emerald-500'
    };
}
// ─── Meeting Reminder Helpers ───────────────────────────────
function getMeetingCountdown(startDateTime) {
    const now = new Date();
    const start = new Date(startDateTime);
    const diffMs = start.getTime() - now.getTime();
    if (diffMs < 0) return {
        text: 'Started',
        urgency: 'urgent'
    };
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);
    if (diffMins <= 15) return {
        text: `In ${diffMins}m`,
        urgency: 'urgent'
    };
    if (diffMins <= 60) return {
        text: `In ${diffMins}m`,
        urgency: 'warning'
    };
    if (diffHours < 24) return {
        text: `In ${diffHours}h ${diffMins % 60}m`,
        urgency: 'normal'
    };
    return {
        text: `In ${diffDays}d`,
        urgency: 'normal'
    };
}
